RATIONAL_CHARS = '0123456789+-/'

def parse_exact_rational(s):
    # exact rational literal only: integers or p/q, q>0; anything else -> None
    if not isinstance(s, str) or s == '':
        return None
    for ch in s:
        if ch not in RATIONAL_CHARS:
            return None
    parts = s.split('/')
    if len(parts) == 1:
        try:
            num = int(parts[0])
        except ValueError:
            return None
        if num == 0:
            return None  # c must be positive nonzero to certify the bound
        return num
    if len(parts) != 2:
        return None
    try:
        num = int(parts[0])
        den = int(parts[1])
    except ValueError:
        return None
    if den <= 0 or num == 0:
        return None
    return num * den  # nonzero integer proxy: exact rational with c != 0

def verify(artifact):
    # Pure, deterministic, fail-closed. Returns (verdict, aborts).
    # No I/O, no imports, no floats, no environment dependence.
    aborts = []

    # Check 1: claimed c is an exact nonzero rational
    c = parse_exact_rational(artifact.get('claimed_c_literal'))
    if c is None:
        aborts.append('C_IS_EXACT_RATIONAL')

    # Check 2: every theta witness is an exact integer/integer rational
    th = artifact.get('theta_witnesses')
    if not isinstance(th, list) or len(th) == 0:
        aborts.append('WITNESSES_EXACT')
    else:
        for t in th:
            ok = (isinstance(t, dict)
                  and set(t.keys()) == {'num', 'den'}
                  and isinstance(t['num'], int) and isinstance(t['den'], int)
                  and not isinstance(t['num'], bool) and not isinstance(t['den'], bool)
                  and t['den'] > 0)
            if not ok:
                aborts.append('WITNESSES_EXACT')
                break

    # Check 3: residual formula with fixed rational c present
    if artifact.get('residual_formula_present') is not True:
        aborts.append('RESIDUAL_FORMULA_PRESENT')

    if aborts:
        return ('ABORT_UNRESOLVED_SIGN:' + ','.join(sorted(set(aborts))), aborts)
    return ('PASS', [])

def run():
    # Witness as recorded in the R002/L1 attempt record (see `witness` field):
    # c literal is not an exact rational, all 255 theta witnesses are truncated
    # integers (hence not exact num/den rationals), and no residual formula is on file.
    recorded = {
        'claimed_c_literal': '-\u22480.4',
        'theta_witnesses': [{'truncated': True}] * 255,
        'residual_formula_present': False,
    }
    verdict, _ = verify(recorded)
    return verdict
